inputs = ['bx', 'wjweh', 'kuhiwc', 'dcwj', 'xugizb']
outputs = ['bx', 'ejeeh', 'kuhiec', 'dcej', 'xubceizb']

# Let me look at character by character differences
print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find positions where they differ
        diff_positions = []
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                diff_positions.append((j, char_in, char_out))

        # Check if one string is longer
        if len(inp) != len(outp):
            if len(inp) > len(outp):
                # Extra chars in input
                for j in range(len(outp), len(inp)):
                    diff_positions.append((j, inp[j], None))
            else:
                # Extra chars in output
                for j in range(len(inp), len(outp)):
                    diff_positions.append((j, None, outp[j]))

        print(f"  Differences at positions: {diff_positions}")
    print()

